/**
 * The deploy lock: the single lock for operations that change the running
 * flows. Deployments through the Admin API (`POST /flows`, `/flow`), changes
 * of the flows run state (`POST /flows/state`) and project switches run under
 * this lock; a second operation waits until the first one completes.
 *
 * The lock is taken only where an operation enters the runtime (runtime api,
 * project switch) - never in `flows/index.js` - and is not re-entrant: code
 * running under the lock must not call another entry point that takes it.
 * @module
 */

const Mutex = require('async-mutex').Mutex;
const mutex = new Mutex();

/**
 * Runs `fn` under the deploy lock. The lock is released when the promise
 * returned by `fn` settles, or if `fn` throws.
 * @param {Function} fn - the function to run; may return a promise
 * @return {Promise} - resolves/rejects with the result of `fn`
 */
function runExclusive(fn) {
    return mutex.runExclusive(fn);
}

/**
 * Whether the deploy lock is currently held.
 * @return {boolean}
 */
function isLocked() {
    return mutex.isLocked();
}

module.exports = {
    runExclusive,
    isLocked
};
